  on conflict (id) do nothing;
insert into fiche_versions (subject_id, version, content, published_at) values ('eclampsia', 1, $fiche${"kind": "fiche", "meta": {"title": "Éclampsie", "topic_id": "eclampsie", "template": "urgence", "audience": ["MG", "urgences"], "version": "0.1", "status": "draft", "reviewer": null, "reviewed_at": null, "siblings": [], "sources": [{"source_id": "insp-eclampsie-2018", "type": "full_guideline", "title": "Conduite à tenir devant une éclampsie", "citation": "Ministère de la Santé, de la Population et de la Réforme Hospitalière ; Institut National de Santé Publique. Date non indiquée dans le document.", "licence": ""}], "excluded_by_audience": [], "quote_check": "73/73", "motifs": [], "synonymes": [], "specialite": "Obstétrique"}, "sections": {"1_essentiel": {"state": "filled", "elements": [{"id": "eclampsie-001", "text": "Toute crise convulsive après le 4e mois de grossesse = éclampsie jusqu'à preuve du contraire, à traiter comme telle.", "type": "info", "condition": null, "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 1, "quote": "Toute crise convulsive survenant après le 4ème mois de la grossesse doit être considérée comme une éclampsie jusqu’à preuve du contraire et doit donc être traitée comme une éclampsie"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-002", "text": "Urgence obstétricale : 1re priorité, stabiliser l'état maternel.", "type": "info", "condition": null, "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 1, "quote": "L’éclampsie est une urgence obstétricale et la 1ère priorité est de stabiliser l’état maternel"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-003", "text": "L'urgence maternelle prime sur l'état fœtal.", "type": "info", "condition": null, "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 1, "quote": "L’urgence maternelle prime sur l’état fœtal"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}]}, "2_presentation": {"state": "filled", "signes_typiques": [{"id": "eclampsie-004", "text": "Convulsion tonico-clonique et/ou trouble de la conscience, dans un contexte d'HTA, sans problème neurologique antérieur.", "type": "info", "condition": null, "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 1, "quote": "Eclampsie = Convulsion tonico-clonique et/ou trouble de la conscience dans un contexte d’hypertension artérielle en l’absence d’un problème neurologique antérieur."}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}], "formes_trompeuses": [], "examen_clinique": [], "criteres_diagnostiques": [], "diagnostics_differentiels": []}, "3_champ": {"state": "filled", "elements": [{"id": "eclampsie-005", "text": "Survient après la 20e SA.", "type": "info", "condition": null, "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 1, "quote": "L’éclampsie survient après la 20ème semaine d’aménorrhée"}, "translated": false, "grade": null, "risk": "low", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-006", "text": "Répartition : 50 % pendant la grossesse, 30 % pendant l'accouchement, 20 % dans le post-partum.", "type": "info", "condition": null, "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 1, "quote": "dans 50 % des cas pendant la grossesse dans 30 % pendant l’accouchement et dans 20% dans le post-partum"}, "translated": false, "grade": null, "risk": "low", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}]}, "4_gravite": {"state": "filled", "signes_de_gravite": [{"id": "eclampsie-007", "text": "Crises répétées, état de mal convulsif et/ou troubles de la conscience (Glasgow ≤ 9).", "type": "info", "condition": null, "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 4, "quote": "Crise tonico-clonique répétée, Etat de mal convulsif et/ou troubles de la conscience (Glasgow ≤ 9)"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-008", "text": "Convulsions persistantes malgré le bolus de MgSO4, nouvelles crises sous MgSO4, ou coma.", "type": "info", "condition": null, "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 4, "quote": "Si la patiente, malgré le bolus de sulfate de magnésium, continue à convulser ou présente de nouvelles crises sous sulfate de magnésium, ou sombre dans le coma"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}], "gestes_immediats": {"state": "filled", "elements": [{"id": "eclampsie-009", "text": "Position latérale de sécurité sur le côté gauche.", "type": "action", "condition": null, "order": 1, "source": {"source_id": "insp-eclampsie-2018", "page": 2, "quote": "Disposer la patiente en position latérale de sécurité sur le côté gauche"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-010", "text": "Installer la patiente à l'abri du risque traumatique (chute).", "type": "action", "condition": null, "order": 2, "source": {"source_id": "insp-eclampsie-2018", "page": 2, "quote": "Mettre la patiente dans un endroit permettant d’éviter le risque traumatique (comme une chute de la parturiente)"}, "translated": false, "grade": null, "risk": "medium", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-011", "text": "Si inconsciente : canule de Guedel (aspiration des sécrétions, prévention de la chute et de la morsure de la langue).", "type": "conditional", "condition": "patiente inconsciente", "order": 3, "source": {"source_id": "insp-eclampsie-2018", "page": 2, "quote": "Libérer les voies aériennes : placer une Canule de Guedel si la patiente est inconsciente"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-012", "text": "Oxygène nasal 6 à 8 l/min, ou à défaut au masque.", "type": "action", "condition": null, "order": 4, "source": {"source_id": "insp-eclampsie-2018", "page": 2, "quote": "Oxygéner par voie nasale avec un débit de 6 à 8 l/minute ou à défaut au masque"}, "translated": false, "grade": null, "risk": "medium", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-013", "text": "Voie veineuse périphérique 16 G (grise) ou 18 G (verte).", "type": "action", "condition": null, "order": 5, "source": {"source_id": "insp-eclampsie-2018", "page": 2, "quote": "Poser un abord veineux périphérique : 16 G (grise) ou 18 G (verte)"}, "translated": false, "grade": null, "risk": "medium", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-014", "text": "Administrer immédiatement le MgSO4 à la dose d'attaque, en 1re intention (voir posologies).", "type": "action", "condition": null, "order": 6, "source": {"source_id": "insp-eclampsie-2018", "page": 2, "quote": "Administrer immédiatement du sulfate de magnésium (MgSO4) à la dose d’attaque en 1ère intention"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-015", "text": "Sondage vésical systématique.", "type": "action", "condition": null, "order": 7, "source": {"source_id": "insp-eclampsie-2018", "page": 2, "quote": "Sondage vésical systématique avec surveillance de la diurèse"}, "translated": false, "grade": null, "risk": "medium", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-016", "text": "Dès la fin du traitement de la crise, passer au traitement d'entretien.", "type": "action", "condition": null, "order": 8, "source": {"source_id": "insp-eclampsie-2018", "page": 2, "quote": "Dès la fin de du traitement de la crise, passer au traitement d’entretien"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}]}, "decision_initiale": {"state": "non_traité", "elements": []}}, "5_conduite": {"state": "filled", "nodes": [{"node": "Après stabilisation maternelle : évacuation utérine", "branches": [{"id": "eclampsie-017", "text": "Dès que l'état maternel est stable, évacuer l'utérus le plus rapidement possible, par n'importe quelle voie ; la césarienne est le plus souvent pratiquée.", "type": "action", "condition": null, "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 1, "quote": "Dès que l’état maternel est considéré stable, il est impératif d’évacuer l’utérus le plus rapidement possible par n’importe quelle voie."}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-018", "text": "Bloc disponible : dès stabilisation, évacuer l'utérus ; appeler le chirurgien en l'absence d'obstétricien.", "type": "conditional", "condition": "bloc opératoire disponible", "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 3, "quote": "Dès stabilisation, procéder à l’évacuation de l’utérus - Appeler le chirurgien en cas d’absence d’obstétricien"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-019", "text": "Bloc non disponible, dilatation ≥ 6 cm : accoucher par voie basse immédiatement.", "type": "conditional", "condition": "bloc non disponible ET dilatation ≥ 6 cm", "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 3, "quote": "Dilatation >=6 cm"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": ["quote: libellé 'Accoucher la patiente par voie basse immédiatement' dans une case séparée du schéma, à vérifier visuellement"], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-020", "text": "Bloc non disponible, dilatation < 4 cm : transférer vers une structure disposant d'un bloc.", "type": "conditional", "condition": "bloc non disponible ET dilatation < 4 cm", "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 3, "quote": "Dilatation < 4 cm"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": ["quote: libellé 'Transférer la patiente vers une structure disposant d’un bloc opératoire' dans une case séparée du schéma, à vérifier visuellement"], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-021", "text": "Dilatation entre 4 et 6 cm : non traité par la source. Attitudes indicatives ; le médecin apprécie l'imminence de l'accouchement.", "type": "info", "condition": "bloc non disponible ET dilatation 4 à 6 cm", "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 3, "quote": "Les attitudes préconisées, en fonction de l’état d’avancement de la dilatation, sont données à titre indicatif. Le médecin devra apprécier l’imminence de l’accouchement"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": ["conduite pour dilatation 4 à 6 cm"], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-022", "text": "Accouchement imminent : favoriser la voie basse ; sinon, privilégier l'extraction par voie haute.", "type": "conditional", "condition": "accouchement imminent", "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 3, "quote": "En cas d’accouchement imminent, on favorisera la voie basse. En dehors de ce cas de figure, c’est l’extraction par voie haute qui doit être privilégiée."}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}]}, {"node": "Crises répétées, état de mal ou Glasgow ≤ 9", "branches": [{"id": "eclampsie-023", "text": "Les mesures de réanimation sont au premier plan.", "type": "action", "condition": null, "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 4, "quote": "Les mesures de réanimation sont au 1er plan"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-024", "text": "Dans les deux cas : anesthésie générale, induction à séquence rapide (Rapifen) + manœuvre de Sellick, Penthotal ou Diprivan + curare (Esméron), intubation orotrachéale + ventilation assistée.", "type": "action", "condition": "utérus plein ou vide", "order": 1, "source": {"source_id": "insp-eclampsie-2018", "page": 4, "quote": "Effectuer une anesthésie générale avec :"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-025", "text": "Utérus plein (pré-partum) : extraire le fœtus en urgence par voie haute ; sans bloc, transférer vers la structure adéquate.", "type": "conditional", "condition": "utérus plein (pré-partum)", "order": 2, "source": {"source_id": "insp-eclampsie-2018", "page": 4, "quote": "Extraire le fœtus en urgence par voie haute – si la structure ne dispose pas de bloc, assurer le transfert vers la structure adéquate"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-026", "text": "Maintenir le MgSO4 en dose d'entretien, 1 à 2 g/h pendant 48 h, et contrôler l'HTA par nicardipine (voir posologies).", "type": "action", "condition": null, "order": 3, "source": {"source_id": "insp-eclampsie-2018", "page": 4, "quote": "Maintenir le Sulfate de Magnésium en dose d’entretien : en perfusion continue de 1 g à 2 g par heure pendant 48 heures"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}]}, {"node": "Surdosage en MgSO4", "branches": [{"id": "eclampsie-027", "text": "Arrêter la perfusion de MgSO4.", "type": "action", "condition": null, "order": 1, "source": {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Arrêter la perfusion de MgSO4"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-028", "text": "Perfuser du gluconate de calcium (antagoniste du magnésium, voir posologies).", "type": "action", "condition": null, "order": 2, "source": {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Perfuser du gluconate de calcium"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-029", "text": "Administrer de l'oxygène.", "type": "action", "condition": null, "order": 3, "source": {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Administrer de l’oxygène"}, "translated": false, "grade": null, "risk": "medium", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-030", "text": "Si arrêt respiratoire : intubation trachéale + ventilation assistée.", "type": "conditional", "condition": "arrêt respiratoire", "order": 4, "source": {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Effectuer une intubation trachéale associée à une ventilation assistée si arrêt respiratoire"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}]}]}, "6_examens": {"state": "filled", "elements": [{"id": "eclampsie-031", "text": "Bilan rénal de référence : urée, créatininémie.", "type": "action", "condition": null, "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 2, "quote": "bilan rénal de référence (urée, créatinémie)"}, "translated": false, "grade": null, "risk": "medium", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-032", "text": "Pendant l'entretien : surveiller urée et créatinine.", "type": "action", "condition": null, "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 3, "quote": "Surveiller les ROT, la FR, la diurèse horaire, l’urée et la créatinine"}, "translated": false, "grade": null, "risk": "medium", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-033", "text": "Imagerie si : Coma post-critique > 6 h.", "type": "conditional", "condition": "indication d'imagerie", "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Si coma post critique > 6 heures"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-034", "text": "Imagerie si : Signes de localisation évoquant un AVC ou une thrombose veineuse cérébrale.", "type": "conditional", "condition": "indication d'imagerie", "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Si apparition de signes de localisation en faveur d’un AVC ou d’une thrombose veineuse cérébrale (hémorragie, TVC)"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-035", "text": "Imagerie si : Convulsions persistantes.", "type": "conditional", "condition": "indication d'imagerie", "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Si convulsions persistantes"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-036", "text": "Imagerie si : Convulsions avant la 20e SA.", "type": "conditional", "condition": "indication d'imagerie", "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Si convulsions survenant avant la 20ème SA"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-037", "text": "Imagerie si : Éclampsie survenant 48 h après l'accouchement.", "type": "conditional", "condition": "indication d'imagerie", "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Si éclampsie survient 48 heures après l’accouchement"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-038", "text": "Imagerie si : Éclampsie réfractaire malgré un traitement adéquat par MgSO4.", "type": "conditional", "condition": "indication d'imagerie", "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Si éclampsie réfractaire (récidive des convulsions) malgré un traitement adéquat par MgSO4"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-039", "text": "Imagerie si : Troubles visuels persistants : IRM à la recherche d'un PRES.", "type": "conditional", "condition": "indication d'imagerie", "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Si persistance des troubles visuels : IRM à la recherche d’une encéphalopathie postérieure réversible (PRES syndrome)"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}]}, "7_traitement": {"state": "filled", "elements": [{"id": "eclampsie-040", "text": "Prévention de la récidive après la crise : repose sur le MgSO4.", "type": "action", "condition": null, "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 3, "quote": "La prise en charge de la patiente après arrêt de la crise tonico-clonique pour prévenir la récidive : est basée sur l’administration du Sulfate de Magnésium (MgSO4)"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-041", "text": "Contrôler l'HTA par nicardipine en perfusion continue, sur une 2e voie d'abord.", "type": "action", "condition": null, "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 3, "quote": "Contrôler l’HTA en administrant de la Nicardipine (Loxen*) en perfusion continue de 1 à 6 mg/heure en utilisant une 2ème voie d’abord"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}], "contre_indications": {"state": "filled", "elements": [{"id": "eclampsie-042", "text": "MgSO4 contre-indiqué si insuffisance rénale sévère (clairance de la créatinine < 30 ml/min/1,73 m²).", "type": "conditional", "condition": "insuffisance rénale sévère", "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 1, "quote": "Contre Indication au MgSO4 : insuffisance rénale sévère (clairance de la créatinine inférieure à 30 ml/min/1,73 m²)"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}]}, "posologies": [{"id": "eclampsie-pos01", "drug_dci": "sulfate de magnésium", "dose": "4 g (≈ 2,5 ampoules)", "dose_max": null, "route": "IV", "administration": "Diluer dans 150 cc de SSI ; ampoule de 1,5 g pour 10 ml", "frequency_or_duration": "en 20 mn", "condition": "dose d'attaque", "risk": "high", "source": {"source_id": "insp-eclampsie-2018", "page": 2, "quote": "Diluer 4g (≈ 2,5 ampoules) de Sulfate de Magnésium dans 150 cc de SSI à passer en IV en 20 mn (présentation : ampoule de 1,5 g pour 10 ml)"}, "translated": false, "missing": [], "titration": null, "algerie": {"brands": [], "statut": null}, "note": "Incohérence source : 4 g = 2,67 ampoules de 1,5 g, pas 2,5."}, {"id": "eclampsie-pos02", "drug_dci": "sulfate de magnésium", "dose": "1,5 à 2 g (1 à 1,5 ampoules)", "dose_max": "8 g cumulés pendant la 1re heure", "route": "IV (perfusion)", "administration": null, "frequency_or_duration": "en 20 mn", "condition": "récidive", "risk": "high", "source": {"source_id": "insp-eclampsie-2018", "page": 2, "quote": "En cas de récidive, injection d’une dose additionnelle de 1,5 à 2 g (1 à 1,5 ampoules) en perfusion à passer en 20 mn sans dépasser la dose cumulée de 8 g de Sulfate de Magnésium pendant la 1ère heure de traitement"}, "translated": false, "missing": ["administration"], "titration": null, "algerie": {"brands": [], "statut": null}, "note": null}, {"id": "eclampsie-pos03", "drug_dci": "sulfate de magnésium", "dose": "1 à 2 g/h ; 4 ampoules (6 g) dans 60 cc de SSI", "dose_max": null, "route": "IV (seringue électrique)", "administration": "vitesse 10 cc/h ; 1 cc = 0,1 g", "frequency_or_duration": "seringue en 6 h, renouvelée toutes les 6 h pendant 48 h", "condition": "entretien, SE disponible", "risk": "high", "source": {"source_id": "insp-eclampsie-2018", "page": 3, "quote": "Diluer 4 ampoules (6g) de MgSO4 dans 60 cc de SSI à passer à la seringue en 6H (vitesse de 10 cc/h ; 1 cc = 0,1g)"}, "translated": false, "missing": [], "titration": null, "algerie": {"brands": [], "statut": null}, "note": null}, {"id": "eclampsie-pos04", "drug_dci": "sulfate de magnésium", "dose": "2,5 ampoules (3 g) dans 300 cc de SSI", "dose_max": null, "route": "IV (perfusion)", "administration": null, "frequency_or_duration": "en 3 h, à renouveler pour couvrir 48 h", "condition": "entretien, SE non disponible", "risk": "high", "source": {"source_id": "insp-eclampsie-2018", "page": 3, "quote": "Diluer 2,5 ampoules (3g) de MgSO4 dans 300 cc de SSI à passer en 3H"}, "translated": false, "missing": ["administration"], "titration": null, "algerie": {"brands": [], "statut": null}, "note": "Incohérence source : 2,5 ampoules de 1,5 g = 3,75 g, pas 3 g. À trancher par le relecteur."}, {"id": "eclampsie-pos05", "drug_dci": "nicardipine", "dose": "1 à 6 mg/h ; 1 ampoule de 10 mg dans 20 cc de SSI", "dose_max": null, "route": "IV (seringue électrique, 2e voie)", "administration": "vitesse 1 cc/h ; « 1 cc = 1 g » (tel qu'écrit)", "frequency_or_duration": "en 6 à 10 h selon les chiffres tensionnels", "condition": "SE disponible", "risk": "high", "source": {"source_id": "insp-eclampsie-2018", "page": 3, "quote": "Diluer 1 ampoule de 10 mg (dans 1cc, il y a 1 mg) dans 20 cc de SSI à passer en 6 à 10 h (vitesse de 1 cc/h ; 1 cc = 1 g) selon les chiffres tensionnels"}, "translated": false, "missing": [], "titration": null, "algerie": {"brands": [], "statut": null}, "note": "ERRATUM SOURCE : « 1 cc = 1 g » est une erreur d'unité. De plus, 20 cc à 1 cc/h durent 20 h (pas 6 à 10 h) et donnent 0,5 mg/h, sous la fourchette 1 à 6 mg/h. Ne pas corriger sans validation du relecteur."}, {"id": "eclampsie-pos06", "drug_dci": "nicardipine", "dose": "1 ampoule dans 200 cc de SSI", "dose_max": null, "route": "IV (perfusion, 2e voie)", "administration": null, "frequency_or_duration": "en 4 à 6 h selon les chiffres tensionnels", "condition": "SE non disponible", "risk": "high", "source": {"source_id": "insp-eclampsie-2018", "page": 3, "quote": "Diluer une ampoule dans 200 cc de SSI à passer en 4 à 6 h selon les chiffres tensionnels"}, "translated": false, "missing": ["administration"], "titration": null, "algerie": {"brands": [], "statut": null}, "note": null}, {"id": "eclampsie-pos07", "drug_dci": "gluconate de calcium", "dose": "1 g dans 50 ml de SSI", "dose_max": null, "route": "IV (perfusion)", "administration": null, "frequency_or_duration": "en 10 mn", "condition": "surdosage en MgSO4", "risk": "high", "source": {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Perfuser du gluconate de calcium : 1 g dans 50 ml de SSI à faire passer en 10 mn"}, "translated": false, "missing": ["administration"], "titration": null, "algerie": {"brands": [], "statut": null}, "note": null}, {"id": "eclampsie-pos08", "drug_dci": "alfentanil", "dose": "", "dose_max": null, "route": "", "administration": null, "frequency_or_duration": "", "condition": "anesthésie générale, crises répétées", "risk": "high", "source": {"source_id": "insp-eclampsie-2018", "page": 4, "quote": "Induction à séquence rapide (morphinique : Rapifen)"}, "translated": false, "missing": ["dose", "route", "frequency_or_duration"], "titration": null, "algerie": {"brands": [], "statut": null}, "note": "Cité par nom commercial (Rapifen) ; DCI déduite, à confirmer par le relecteur. Aucune dose dans la source."}, {"id": "eclampsie-pos09", "drug_dci": "thiopental", "dose": "", "dose_max": null, "route": "", "administration": null, "frequency_or_duration": "", "condition": "anesthésie générale, crises répétées", "risk": "high", "source": {"source_id": "insp-eclampsie-2018", "page": 4, "quote": "Penthotal ou Diprivan + curare (Esméron)"}, "translated": false, "missing": ["dose", "route", "frequency_or_duration"], "titration": null, "algerie": {"brands": [], "statut": null}, "note": "Cité par nom commercial (Penthotal) ; DCI déduite, à confirmer par le relecteur. Aucune dose dans la source."}, {"id": "eclampsie-pos10", "drug_dci": "propofol", "dose": "", "dose_max": null, "route": "", "administration": null, "frequency_or_duration": "", "condition": "anesthésie générale, crises répétées", "risk": "high", "source": {"source_id": "insp-eclampsie-2018", "page": 4, "quote": "Penthotal ou Diprivan + curare (Esméron)"}, "translated": false, "missing": ["dose", "route", "frequency_or_duration"], "titration": null, "algerie": {"brands": [], "statut": null}, "note": "Cité par nom commercial (Diprivan) ; DCI déduite, à confirmer par le relecteur. Aucune dose dans la source."}, {"id": "eclampsie-pos11", "drug_dci": "rocuronium", "dose": "", "dose_max": null, "route": "", "administration": null, "frequency_or_duration": "", "condition": "anesthésie générale, crises répétées", "risk": "high", "source": {"source_id": "insp-eclampsie-2018", "page": 4, "quote": "Penthotal ou Diprivan + curare (Esméron)"}, "translated": false, "missing": ["dose", "route", "frequency_or_duration"], "titration": null, "algerie": {"brands": [], "statut": null}, "note": "Cité par nom commercial (Esméron) ; DCI déduite, à confirmer par le relecteur. Aucune dose dans la source."}]}, "8_ne_pas_faire": {"state": "filled", "elements": [{"id": "eclampsie-043", "text": "Ne pas administrer de nicardipine en bolus.", "type": "action", "condition": null, "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 1, "quote": "Ne pas administrer de Nicardipine en bolus"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-044", "text": "Ne pas retarder la prise en charge de la crise par la recherche d'une étiologie.", "type": "action", "condition": null, "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 1, "quote": "La recherche d’une étiologie ne doit pas retarder la prise en charge de la crise convulsive"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}]}, "9_orientation": {"state": "filled", "elements": [{"id": "eclampsie-045", "text": "Transfert uniquement après stabilisation neurologique et tensionnelle : FC 80 à 100/min, FR > 12/min, PAD 90 à 105 mmHg, PAM 105 à 125 mmHg.", "type": "row", "condition": null, "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 1, "quote": "La patiente ne doit être transférée qu’une fois stabilisée sur le plan neurologique et tensionnel avec une FC (80-100 btt/mn), une FR > 12 cycles/mn et une TA : PAD (entre 90 et 105 mm de Hg) et PAM : (entre 105 -125 mm de Hg)"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-046", "text": "Pendant le transfert, obligatoirement : deux voies veineuses, MgSO4 en entretien + antihypertenseur, oxygène, accompagnée d'un médecin ou éventuellement d'une sage-femme.", "type": "action", "condition": null, "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 1, "quote": "Durant le transfert, la patiente doit être obligatoirement :"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-047", "text": "Structure avec bloc : prévoir le transfert ultérieur en réanimation.", "type": "conditional", "condition": "structure avec bloc", "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 2, "quote": "De réanimation si l’on est dans une structure disposant d’un bloc opératoire"}, "translated": false, "grade": null, "risk": "medium", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-048", "text": "Structure sans bloc : prévoir le transfert vers un service d'obstétrique ou pourvu d'un bloc.", "type": "conditional", "condition": "structure sans bloc", "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 2, "quote": "D’obstétrique ou pourvu d’un bloc opératoire si l’on est dans une structure sanitaire ne disposant pas de bloc opératoire"}, "translated": false, "grade": null, "risk": "medium", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-049", "text": "Avec bloc : transférer en réanimation une fois la crise maîtrisée et l'utérus évacué.", "type": "conditional", "condition": "bloc opératoire disponible", "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 3, "quote": "Transférer la patiente vers un service de réanimation, une fois la crise maitrisée et l’utérus évacué"}, "translated": false, "grade": null, "risk": "medium", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-050", "text": "Sans bloc et sans médecin : gestes immédiats (PLS gauche, Guedel, O2, VVP), puis transfert immédiat vers une structure disposant d'un bloc.", "type": "conditional", "condition": "ni bloc ni médecin dans la structure", "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Transférer immédiatement la patiente vers une structure disposant d’un bloc opératoire"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}]}, "10_surveillance": {"state": "filled", "elements": [{"id": "eclampsie-051", "text": "Pendant la crise : TA, FC, FR, SpO2 toutes les 5 minutes.", "type": "action", "condition": null, "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 2, "quote": "Monitorer la TA, FC, FR, SPO2 toutes les 5 minutes"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-052", "text": "Surveillance de la diurèse.", "type": "action", "condition": null, "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 2, "quote": "Sondage vésical systématique avec surveillance de la diurèse"}, "translated": false, "grade": null, "risk": "medium", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-053", "text": "Pendant l'entretien : monitorage continu TA, FC, FR, SpO2.", "type": "action", "condition": null, "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 3, "quote": "Monitorer en continue la TA, FC, FR, SPO2."}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-054", "text": "Pendant l'entretien : surveiller les ROT, la FR, la diurèse horaire.", "type": "action", "condition": null, "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 3, "quote": "Surveiller les ROT, la FR, la diurèse horaire"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-055", "text": "Signe de surdosage en MgSO4 : Abolition des ROT.", "type": "row", "condition": "surveillance du MgSO4", "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Abolition Des ROT"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-056", "text": "Signe de surdosage en MgSO4 : Faiblesse musculaire, flush cutané.", "type": "row", "condition": "surveillance du MgSO4", "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Faiblesse Musculaire, Flush Cutané"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-057", "text": "Signe de surdosage en MgSO4 : Nausées, vomissements.", "type": "row", "condition": "surveillance du MgSO4", "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Nausées, Vomissement"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-058", "text": "Signe de surdosage en MgSO4 : Somnolence.", "type": "row", "condition": "surveillance du MgSO4", "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Somnolence"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-059", "text": "Signe de surdosage en MgSO4 : Diplopie ou troubles de l'élocution.", "type": "row", "condition": "surveillance du MgSO4", "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Diplopie Ou Troubles De L’élocution"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-060", "text": "Signe de surdosage en MgSO4 : Paralysie.", "type": "row", "condition": "surveillance du MgSO4", "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Paralysie"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}, {"id": "eclampsie-061", "text": "Signe de surdosage en MgSO4 : Arrêt respiratoire, arrêt cardiaque.", "type": "row", "condition": "surveillance du MgSO4", "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Arrêt Respiratoire, arrêt cardiaque"}, "translated": false, "grade": null, "risk": "high", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}]}, "11_suivi": {"state": "non_traité", "elements": [], "conseils_patient": []}, "12_ordonnance": {"state": "sans_objet", "elements": []}, "13_definitions": {"state": "filled", "elements": [{"id": "eclampsie-062", "text": "SE : seringue électrique.", "type": "info", "condition": null, "order": null, "source": {"source_id": "insp-eclampsie-2018", "page": 3, "quote": "1 : seringue électrique"}, "translated": false, "grade": null, "risk": "low", "origin": "explicit", "conflict_group": null, "variant_group": null, "missing": [], "refs": [], "attached_to": [], "delai": null}]}}}$fiche$::jsonb, null)
